"use client"
import * as React from "react"
import { animate, motion, useMotionValue } from "motion/react"
import { cn } from "@/lib/utils"
import { shapeData } from "@/lib/cojeev/shape-data"
import { signatureShapePaths, type SignatureShapeName } from "@/lib/cojeev/signature-shapes"
import { useChoreography } from "@/lib/cojeev-motion/choreography"
import { useMotionVisibility } from "@/lib/cojeev-motion/use-motion-visibility"
import { assignMotionRef } from "@/lib/cojeev-motion/refs"
export type ShapeProps = React.ComponentProps<"span"> & { name?: string; as?: React.ElementType }
export function Shape({as:Tag="i",name="star-4",className,style,...props}:ShapeProps){
 const mask=shapeData[name];
 if(!mask) throw new Error(`Unknown Cojeev shape: ${name}`)
 return <Tag data-slot="shape" aria-hidden="true" className={cn("v-shape inline-block h-[1em] w-[1em] shrink-0 bg-[var(--c,currentColor)]",`-${name}`,className)} style={{...style,"--m":mask,mask:"var(--m) center / contain no-repeat",WebkitMask:"var(--m) center / contain no-repeat"} as React.CSSProperties} {...props}/>
}
export const shapeNames=Object.keys(shapeData)
export const signatureShapeNames=Object.keys(signatureShapePaths) as SignatureShapeName[]
export type { SignatureShapeName }
export type ShapeMorphProps = Omit<React.ComponentProps<"svg">, "name"> & {
 name?: SignatureShapeName
 variant?: "fill" | "outline"
 /** Omit for a decorative shape; supply when the graphic carries meaning. */
 label?: string
}
/** Original fixed-topology silhouettes; changing name retargets the visible path. */
export function ShapeMorph({name="daisy-12",variant="fill",label,className,ref,...props}:ShapeMorphProps){
 const host=React.useRef<SVGSVGElement>(null)
 const hostRef=React.useCallback((element:SVGSVGElement|null)=>{host.current=element;return assignMotionRef(ref,element)},[ref])
 const {quiet,transition}=useChoreography()
 const {enabled,inView}=useMotionVisibility(host)
 const target=signatureShapePaths[name]
 if(!target)throw new Error(`Unknown Cojeev signature shape: ${name}`)
 const path=useMotionValue(target)
 React.useEffect(()=>{
  if(quiet||!enabled||!inView){path.jump(target);return}
  const animation=animate(path,target,transition)
  return ()=>animation.stop()
 },[target,quiet,enabled,inView,path,transition])
 return <svg {...props} ref={hostRef} data-slot="shape-morph" data-shape={name} data-variant={variant} className={cn("v-shape-morph",className)} viewBox="0 0 100 100" role={label?"img":undefined} aria-label={label} aria-hidden={label?undefined:true} focusable="false">
  <motion.path d={path} fill={variant==="fill"?"currentColor":"none"} stroke={variant==="outline"?"currentColor":"none"} strokeWidth={variant==="outline"?2:0} vectorEffect="non-scaling-stroke" />
 </svg>
}

@layer cojeev-states {
.v-shape-morph { display: block; width: 100%; height: 100%; overflow: visible; }
.v-shape-explorer { display: grid; gap: 24px; min-width: 0; width: 100%; }
.v-shape-explorer__stage { display: grid; grid-template-columns: minmax(180px,.85fr) minmax(0,1fr); gap: 32px; align-items: center; padding: 28px; border: 1px solid var(--v-border); border-radius: var(--r-card); background: linear-gradient(135deg,color-mix(in oklab,var(--v-pink) 20%,var(--v-canvas)),var(--v-canvas)); }
.v-shape-explorer__art { width: min(100%,240px); aspect-ratio: 1; margin-inline: auto; color: var(--shape-color); filter: drop-shadow(0 8px 12px color-mix(in oklab,var(--shape-color) 12%,transparent)); }
.v-shape-explorer__caption { display: grid; gap: 12px; justify-items: start; min-width: 0; }
.v-shape-explorer__caption :is(h3,p) { margin: 0; }
.v-shape-explorer__palette { display: flex; gap: 4px; flex-wrap: wrap; }
.v-shape-explorer__palette button[aria-pressed="true"] { background: var(--v-pink-soft); box-shadow: inset 0 0 0 1px var(--v-brand); }
.v-shape-explorer__choices { display: grid; grid-template-columns: repeat(auto-fit,minmax(110px,1fr)); gap: 8px; }
.v-shape-explorer__choice { min-width: 0; height: auto; display: grid; justify-items: center; gap: 10px; padding: 14px 8px; color: var(--shape-color); border-radius: var(--r-card-sm); }
.v-shape-explorer__choice [data-slot="typography"] { color: var(--v-text); font-size: 11px; overflow-wrap: anywhere; }
.v-shape-explorer__choice[aria-pressed="true"] { background: var(--v-pink-soft); box-shadow: inset 0 0 0 1px var(--v-brand); }
.v-shape-explorer__catalog-head { display: grid; gap: 6px; padding-top: 12px; border-top: 1px solid var(--v-border); }
.v-shape-gallery { display: grid; grid-template-columns: repeat(auto-fill,minmax(100px,1fr)); gap: 12px; }
.v-shape-gallery__item { display: grid; justify-items: center; align-content: center; min-width: 0; gap: 12px; padding: 20px 8px; min-height: 112px; color: var(--shape-color); border: 1px solid var(--v-border); border-radius: var(--r-card-sm); }
.v-shape-gallery__item [data-slot="typography"] { font-size: 11px; color: var(--v-text); overflow-wrap: anywhere; }
@media (max-width:600px) {
 .v-shape-explorer__stage { grid-template-columns: 1fr; gap: 20px; padding: 20px; }
 .v-shape-explorer__art { width: 180px; }
 .v-shape-explorer__choices { grid-template-columns: repeat(3,minmax(0,1fr)); }
 .v-shape-explorer__choice { padding: 12px 4px; }
 .v-shape-gallery { grid-template-columns: repeat(3,minmax(0,1fr)); gap: 8px; }
}

}
